#!/usr/bin/env python3
"""Verify the Phase 4 registry, freeze, HTML, PDF, and generation contract agree."""

from __future__ import annotations

import hashlib
import json
import re
from collections import Counter
from pathlib import Path


HERE = Path(__file__).resolve().parent
SUBMISSION = HERE.parents[1]
REPOSITORY = SUBMISSION.parents[2]
REPORT = HERE / "phase4-cross-media-qa.json"

HTMLS = (
    ("report_zh", SUBMISSION / "report" / "proposal.html", "zh", "zh-CN", "report"),
    ("report_en", SUBMISSION / "report" / "proposal.en.html", "en", "en", "report"),
    ("visual_zh", SUBMISSION / "visual" / "index.html", "zh", "zh-CN", "visual"),
    ("visual_en", SUBMISSION / "visual" / "index.en.html", "en", "en", "visual"),
)


def load_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def check_hash_map(mapping: dict[str, str], label: str, base: Path = SUBMISSION) -> tuple[list[dict], list[str]]:
    results = []
    failures = []
    for relative, expected in sorted(mapping.items()):
        path = base / relative
        actual = sha256(path) if path.is_file() else None
        match = actual == expected
        results.append({"path": relative, "base": "repository" if base == REPOSITORY else "submission", "expected_sha256": expected, "actual_sha256": actual, "match": match})
        if not match:
            failures.append(f"{label}: {relative} hash mismatch")
    return results, failures


def normalize_hash_map(mapping: dict) -> dict[str, str]:
    return {
        relative: value["expected_sha256"] if isinstance(value, dict) else value
        for relative, value in mapping.items()
    }


def resolve_fragment(payload: object, fragment: str) -> bool:
    if not fragment:
        return True
    segments = [segment for segment in fragment.strip("/").split("/") if segment]

    def walk(values: list[object], remaining: list[str]) -> list[object]:
        if not remaining:
            return values
        segment = remaining[0]
        if segment == "*":
            expanded: list[object] = []
            for value in values:
                if isinstance(value, list):
                    expanded.extend(value)
                elif isinstance(value, dict):
                    expanded.extend(value.values())
            return walk(expanded, remaining[1:])
        selector = re.fullmatch(r"([^\[]+)\[([^=]+)=([^\]]+)\]", segment)
        selected: list[object] = []
        for value in values:
            candidate: object | None = None
            if isinstance(value, dict) and (selector.group(1) if selector else segment) in value:
                candidate = value[selector.group(1) if selector else segment]
            elif isinstance(value, list) and segment.isdigit() and int(segment) < len(value):
                candidate = value[int(segment)]
            if candidate is None:
                continue
            if selector:
                if not isinstance(candidate, list):
                    continue
                key, expected = selector.group(2), selector.group(3)
                selected.extend(item for item in candidate if isinstance(item, dict) and str(item.get(key)) == expected)
            else:
                selected.append(candidate)
        return walk(selected, remaining[1:])

    return bool(walk([payload], segments))


def audit_display_redteam(payload: dict) -> tuple[dict, list[str]]:
    failures: list[str] = []
    statuses = Counter(str(test.get("status")) for test in payload.get("tests", []))
    computed = {
        "tests": len(payload.get("tests", [])),
        "closed": statuses["closed"],
        "mitigated_with_advisory": statuses["mitigated_with_advisory"],
        "retained_advisory": statuses["retained_advisory"],
        "usage_guidance": statuses["usage_guidance"],
        "semantic_drift": sum(1 for test in payload.get("tests", []) if test.get("semantic_drift") is True),
    }
    summary_matches = payload.get("summary") == computed
    if not summary_matches:
        failures.append(f"display red team: summary {payload.get('summary')} does not equal computed {computed}")

    evidence_results = []
    for test in payload.get("tests", []):
        for reference in test.get("evidence", []):
            file_part, _, fragment = reference.partition("#")
            target = (HERE / file_part).resolve()
            packaged_source = target.suffix.casefold() not in {".py", ".mjs"}
            exists = target.is_file()
            fragment_ok = True
            if exists and fragment:
                fragment_ok = target.suffix.casefold() == ".json" and resolve_fragment(load_json(target), fragment)
            ok = packaged_source and exists and fragment_ok
            evidence_results.append(
                {
                    "test": test.get("id"),
                    "reference": reference,
                    "path_exists": exists,
                    "packaged_source_only": packaged_source,
                    "fragment_resolves": fragment_ok,
                    "ok": ok,
                }
            )
            if not ok:
                failures.append(f"display red team: unresolved evidence {test.get('id')} {reference}")
    return {
        "computed_summary": computed,
        "declared_summary": payload.get("summary"),
        "summary_matches": summary_matches,
        "evidence_references": evidence_results,
        "all_evidence_resolves": all(item["ok"] for item in evidence_results),
    }, failures


def audit_html(key: str, path: Path, lang: str, html_lang: str, kind: str, figures: list[dict]) -> tuple[dict, list[str]]:
    source = path.read_text(encoding="utf-8")
    failures = []
    checks = {
        "document_language": bool(re.search(rf'<html\s+lang="{re.escape(html_lang)}"', source)),
        "one_h1": len(re.findall(r"<h1(?:\s|>)", source)) == 1,
        "eleven_figures": len(re.findall(r"<figcaption(?:\s|>)", source)) == 11,
        "eleven_accessible_original_views": (
            len(re.findall(r"<details class=\"figure-details\"", source)) == 11
            if kind == "report"
            else len(re.findall(r"data-zoom-src=", source)) == 11
        ),
        "canonical_project_name": "Jing-Zhang In Situ" in source,
        "no_remote_requests": not bool(re.search(r'(?:src|href)="https?://', source, flags=re.I)),
        "report_has_no_script": kind != "report" or "<script" not in source.casefold(),
        "skip_target": bool(re.search(r'<a class="(?:phase4-)?skip"[^>]+href="#content"', source)),
        "main_focus_target": bool(re.search(r'<main id="content" tabindex="-1"', source)),
        "language_switch_hreflang": (
            'hreflang="en"' in source if lang == "zh" else 'hreflang="zh-CN"' in source
        ),
        "unified_status_terms": all(
            term.casefold() in source.casefold()
            for term in (
                ("known", "provisional", "unknown", "design-target", "Human Takeover", "停止")
                if lang == "zh"
                else ("known", "provisional", "unknown", "design-target", "Human Takeover", "stop")
            )
        ),
        "residual_boundaries": (
            all(term in source for term in ("容积率", "三处重点区", "12 个", "法律审查", "正式批准"))
            if lang == "zh"
            else (
                ("FAR" in source or "floor area ratio" in source.casefold())
                and "three" in source.casefold()
                and "key areas" in source.casefold()
                and "twelve" in source.casefold()
                and "legal review" in source.casefold()
                and "official approval" in source.casefold()
            )
        ),
    }

    figure_results = []
    for figure in figures:
        figure_id = f"figure-{figure['id'].lower()}" if kind == "report" else figure["slug"]
        start = source.find(f'id="{figure_id}"')
        end = source.find("</figure>", start)
        segment = source[start:end] if start >= 0 and end >= 0 else ""
        title = figure[f"title_{lang}"]
        alt = figure[f"alt_{lang}"]
        mapped = {
            "id": figure["id"],
            "container": figure_id,
            "present": bool(segment),
            "title_matches_registry": title in segment,
            "alt_matches_registry": alt in segment,
            "a3_page": figure["a3_page"],
            "a0_board": figure["a0_board"],
        }
        mapped["ok"] = mapped["present"] and mapped["title_matches_registry"] and mapped["alt_matches_registry"]
        if not mapped["ok"]:
            failures.append(f"{key}: {figure['id']} registry mapping mismatch")
        figure_results.append(mapped)

    for check, passed in checks.items():
        if not passed:
            failures.append(f"{key}: {check} failed")
    return (
        {
            "key": key,
            "path": path.relative_to(SUBMISSION).as_posix(),
            "language": lang,
            "kind": kind,
            "checks": checks,
            "figures": figure_results,
            "failures": failures,
            "ok": not failures,
        },
        failures,
    )


