    REPORT.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(json.dumps({"ok": report["ok"], "html": len(html_results), "figures_per_html": len(figures), "failures": len(failures)}))
